class UnionFind:
    """Points that share a wire endpoint get merged into the same electrical net."""
    def __init__(self):
        self.parent = {}

    def find(self, k):
        self.parent.setdefault(k, k)
        root = k
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[k] != root:
            self.parent[k], k = root, self.parent[k]
        return root

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[ra] = rb


def gate_ports(c):
    """Input/output port coordinates for a gate, matching the layout rules used
    when the circuit was generated: NOT gates are 30 wide with one input;
    2-input AND/OR/XOR gates are 50 wide with inputs offset +-20 vertically."""
    x, y = c["loc"]
    if c["kind"] == "NOT":
        return {"inputs": [(x - 30, y)], "output": (x, y)}
    return {"inputs": [(x - 50, y - 20), (x - 50, y + 20)], "output": (x, y)}


def build_uf(circuit):
    uf = UnionFind()
    for (p1, p2) in circuit["wires"]:
        uf.union(tuple(p1), tuple(p2))
    return uf


def simulate(key, input_values):
    """Given a dict of {pin_label: 0/1} for the circuit's input pins, returns
    (uf, net_value) so callers can look up any point's computed logic level."""
    d = CIRCUIT_DATA[key]
    uf = build_uf(d)
    net_value = {}
    for c in d["components"]:
        if c["kind"] == "pin" and not c.get("output"):
            net_value[uf.find(tuple(c["loc"]))] = input_values.get(c["label"], 0)
    gates = [c for c in d["components"] if c["kind"] != "pin"]
    for _ in range(len(gates) + 1):
        for c in gates:
            ports = gate_ports(c)
            in_vals = [net_value.get(uf.find(p)) for p in ports["inputs"]]
            if any(v is None for v in in_vals):
                continue
            if c["kind"] == "NOT":
                out = 0 if in_vals[0] else 1
            elif c["kind"] == "AND":
                out = 1 if all(v == 1 for v in in_vals) else 0
            elif c["kind"] == "OR":
                out = 1 if any(v == 1 for v in in_vals) else 0
            elif c["kind"] == "XOR":
                out = 1 if in_vals[0] != in_vals[1] else 0
            net_value[uf.find(ports["output"])] = out
    return uf, net_value


def output_values(key, input_values):
    """Convenience: returns {output_pin_label: 0/1} for a given input assignment."""
    d = CIRCUIT_DATA[key]
    uf, net_value = simulate(key, input_values)
    out = {}
    for c in d["components"]:
        if c["kind"] == "pin" and c.get("output"):
            out[c["label"]] = net_value.get(uf.find(tuple(c["loc"])))
    return out


def _nearest_owner(adj, port_owner, start, exclude_edge):
    """Walk outward from `start` along wire segments (skipping exclude_edge,
    since that's the segment we're asking about) until we hit a coordinate
    that's an actual component port, rather than a bare routing bend."""
    if start in port_owner:
        return port_owner[start]
    seen = {start}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nxt in adj[cur]:
            if (cur, nxt) == exclude_edge or (nxt, cur) == exclude_edge:
                continue
            if nxt in seen:
                continue
            if nxt in port_owner:
                return port_owner[nxt]
            seen.add(nxt)
            q.append(nxt)
    return None


