def build_stages(key):
    """Break a circuit into an ordered list of build 'stages' -- ONE
    component per stage, no grouping or summarizing, so every single pin
    and gate gets its own step and its own plain-English caption, no
    matter how large the circuit is. Order respects dependency (a gate's
    stage always comes after whatever feeds it); ties between independent
    components fall back to their original declaration order. Every gate
    gets a stable #N tag (its index in the circuit's component list) so
    later captions can refer back to "gate #N's output" unambiguously,
    even when there are many gates of the same kind. Derived straight from
    the wiring data (not hand-authored), so it's correct for every circuit
    in CIRCUIT_DATA automatically, including future additions.
    """
    d = CIRCUIT_DATA[key]
    components = d["components"]
    wires = [(tuple(p1), tuple(p2)) for p1, p2 in d["wires"]]

    port_owner = {}
    for c in components:
        if c["kind"] == "pin":
            port_owner[tuple(c["loc"])] = c
        else:
            ports = gate_ports(c)
            for p in ports["inputs"]:
                port_owner[p] = c
            port_owner[ports["output"]] = c

    adj = defaultdict(list)
    for p1, p2 in wires:
        adj[p1].append(p2)
        adj[p2].append(p1)

    uf = build_uf(d)
    net_driver = {}
    for c in components:
        if c["kind"] == "pin" and not c.get("output"):
            net_driver[uf.find(tuple(c["loc"]))] = c
        elif c["kind"] != "pin":
            net_driver[uf.find(gate_ports(c)["output"])] = c

    tag = {id(c): i for i, c in enumerate(components)}  # stable #N per component

    levels = {}

    def level_of(c):
        cid = id(c)
        if cid in levels:
            return levels[cid]
        levels[cid] = 0  # guard against (unexpected) cycles
        if c["kind"] == "pin" and not c.get("output"):
            lvl = 0
        elif c["kind"] == "pin":  # output pin
            drv = net_driver.get(uf.find(tuple(c["loc"])))
            lvl = 1 + level_of(drv) if drv else 0
        else:  # gate
            drv_levels = [
                level_of(net_driver[uf.find(p)]) if uf.find(p) in net_driver else 0
                for p in gate_ports(c)["inputs"]
            ]
            lvl = 1 + (max(drv_levels) if drv_levels else 0)
        levels[cid] = lvl
        return lvl

    for c in components:
        level_of(c)

    # one component per stage: order by dependency level, original order breaks ties
    ordered = sorted(range(len(components)), key=lambda i: (levels[id(components[i])], i))
    ordered_components = [components[i] for i in ordered]
    stage_of = {id(c): idx for idx, c in enumerate(ordered_components)}

    stage_wires = [[] for _ in ordered_components]
    for p1, p2 in wires:
        o1 = _nearest_owner(adj, port_owner, p1, (p1, p2))
        o2 = _nearest_owner(adj, port_owner, p2, (p1, p2))
        s1 = stage_of[id(o1)] if o1 else 0
        s2 = stage_of[id(o2)] if o2 else 0
        stage_wires[max(s1, s2)].append([list(p1), list(p2)])

    def source_desc(port_coord):
        drv = net_driver.get(uf.find(port_coord))
        if drv is None:
            return "?"
        if drv["kind"] == "pin":
            return drv["label"]
        return f"gate #{tag[id(drv)]} ({drv['kind']})'s output"

    def caption_for(c):
        if c["kind"] == "pin" and not c.get("output"):
            return f"Place input pin {c['label']}."
        if c["kind"] == "pin":  # output pin
            src = source_desc(tuple(c["loc"]))
            return f"Add output pin {c['label']} — wire it from {src}."
        article = _ARTICLE.get(c["kind"], "a")
        n = tag[id(c)]
        srcs = [source_desc(p) for p in gate_ports(c)["inputs"]]
        if c["kind"] == "NOT":
            return f"Add {article} NOT gate (#{n}) — it inverts {srcs[0]}."
        return f"Add {article} {c['kind']} gate (#{n}) — computes {srcs[0]} {c['kind']} {srcs[1]}."

    stages = []
    for idx, c in enumerate(ordered_components):
        stages.append({
            "components": [c],
            "wires": stage_wires[idx],
            "caption": caption_for(c),
            "tag": tag[id(c)],
        })
    return stages
